package com.learnknow.assignment;
import jakarta.persistence.*; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@SpringBootApplication public class AssignmentServiceApplication {public static void main(String[]a){SpringApplication.run(AssignmentServiceApplication.class,a);}@Entity public static class Assignment{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;public Long courseId;public String title;public String description;public LocalDateTime dueDate;}@Entity public static class Submission{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;public Long assignmentId;public Long userId;@Column(columnDefinition="TEXT")public String code;public String status="SUBMITTED";public Instant submittedAt=Instant.now();}@org.springframework.stereotype.Repository public interface Assignments extends JpaRepository<Assignment,Long>{List<Assignment>findByCourseId(Long id);}@org.springframework.stereotype.Repository public interface Submissions extends JpaRepository<Submission,Long>{Optional<Submission>findByAssignmentIdAndUserId(Long a,Long u);}public record AssignmentRequest(Long courseId,String title,String description,LocalDateTime dueDate){}public record SubmitRequest(Long userId,String code){}@RestController @RequestMapping("/api/assignments")public static class Controller{final AssignmentRepository as;final SubmissionRepository ss;Controller(AssignmentRepository a,SubmissionRepository s){as=a;ss=s;}@GetMapping("/course/{courseId}")List<Assignment>course(@PathVariable Long courseId){return as.findByCourseId(courseId);}@GetMapping("/{id}")Assignment one(@PathVariable Long id){return as.findById(id).orElseThrow(()->new NoSuchElementException("Assignment not found"));}@PostMapping @ResponseStatus(HttpStatus.CREATED)Assignment create(@RequestBody AssignmentRequest r){Assignment a=new Assignment();a.courseId=r.courseId();a.title=r.title();a.description=r.description();a.dueDate=r.dueDate();return as.save(a);}@PostMapping("/{assignmentId}/submit")Submission submit(@PathVariable Long assignmentId,@RequestBody SubmitRequest r){one(assignmentId);Submission s=ss.findByAssignmentIdAndUserId(assignmentId,r.userId()).orElseGet(Submission::new);s.assignmentId=assignmentId;s.userId=r.userId();s.code=r.code();s.submittedAt=Instant.now();return ss.save(s);}@GetMapping("/{assignmentId}/submissions/{userId}")Submission submission(@PathVariable Long assignmentId,@PathVariable Long userId){return ss.findByAssignmentIdAndUserId(assignmentId,userId).orElseThrow(()->new NoSuchElementException("Submission not found"));}}@RestControllerAdvice public static class Errors{@ExceptionHandler(NoSuchElementException.class)@ResponseStatus(HttpStatus.NOT_FOUND)Map<String,String>missing(Exception e){return Map.of("error",e.getMessage());}}}
